import type { Register } from 'claude-code'

// O mod que desenha a previsão vive em ./projeto e é copiado para a pasta
// .claude/skills do projeto, onde o Claude Code o carrega só naquele projeto.
const PASTA_NO_PROJETO = '.claude/skills/monitor-do-contexto-local'

export const ARQUIVOS = [
  '.claude-plugin/plugin.json',
  'hooks/hooks.json',
  'hooks/register.tsx',
  'types/index.d.ts',
] as const

function ehWindows(caminho: string): boolean {
  return /^[A-Za-z]:[\\/]/.test(caminho) || caminho.startsWith('\\\\')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'monitor-ativar',
      description: 'Ativa a previsão do tempo do contexto neste projeto (copia o mod para .claude/skills).',
    })
    await $.command.register({
      name: 'monitor-desativar',
      description: 'Remove a previsão do tempo do contexto deste projeto.',
    })
    await $.command.register({
      name: 'monitor-status',
      description: 'Mostra se a previsão do tempo do contexto está ativa neste projeto.',
    })
    return next(e)
  })

  on('command.run', { command: 'monitor-ativar' }, async $ => {
    const projeto = await $.session.cwd()
    const destino = `${projeto}/${PASTA_NO_PROJETO}`
    const jaAtivo = await $.fs.exists(`${destino}/.claude-plugin/plugin.json`)

    for (const arquivo of ARQUIVOS) {
      const conteudo = await $.fs.read(`${$.plugin.root}/projeto/${arquivo}`)
      await $.fs.write(`${destino}/${arquivo}`, conteudo)
    }

    const acao = jaAtivo ? 'atualizado' : 'ativado'
    return {
      text: [
        `Monitor do contexto ${acao} neste projeto.`,
        `Arquivos copiados para ${PASTA_NO_PROJETO}/.`,
        'Rode /reload-plugins (ou reinicie o Claude Code) para ver a previsão acima do prompt.',
        'Versione essa pasta se quiser que o time também veja a previsão.',
      ].join('\n'),
    }
  })

  on('command.run', { command: 'monitor-desativar' }, async $ => {
    const projeto = await $.session.cwd()
    const destino = `${projeto}/${PASTA_NO_PROJETO}`
    if (!(await $.fs.exists(destino))) {
      return { text: 'O monitor do contexto não está ativo neste projeto.' }
    }

    const argv = ehWindows(projeto)
      ? ['cmd', '/c', 'rmdir', '/s', '/q', destino.replace(/\//g, '\\')]
      : ['rm', '-rf', destino]
    const { exitCode, stderr } = await $.process.run(argv)
    if (exitCode !== 0) {
      return {
        text: `Não consegui remover ${PASTA_NO_PROJETO}/ (${stderr.trim()}). Apague a pasta manualmente.`,
      }
    }
    return {
      text: `Monitor do contexto removido deste projeto. Rode /reload-plugins (ou reinicie o Claude Code) para a linha sumir.`,
    }
  })

  on('command.run', { command: 'monitor-status' }, async $ => {
    const projeto = await $.session.cwd()
    const ativo = await $.fs.exists(`${projeto}/${PASTA_NO_PROJETO}/.claude-plugin/plugin.json`)
    return {
      text: ativo
        ? `Ativo neste projeto (${PASTA_NO_PROJETO}/).`
        : `Inativo neste projeto. Use /monitor-ativar para ativar.`,
    }
  })
}

